export async function withRetry<T>(fn: () => Promise<T>, attempts = 5): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      const base = 200 * 2 ** i;
      const jitter = Math.random() * base * 0.3;
      await new Promise((r) => setTimeout(r, base + jitter));
    }
  }
  throw lastError;
}

