import { createHmac, timingSafeEqual } from "node:crypto";

export function verifyShopifyHmac(rawBody: Buffer, headerHmac: string, secret: string) {
  const digest = createHmac("sha256", secret).update(rawBody).digest();
  const provided = Buffer.from(headerHmac, "base64");
  if (provided.length !== digest.length) return false;
  return timingSafeEqual(provided, digest);
}

