import { exec } from "node:child_process";
import type { Request, Response } from "express";

export function exportTable(req: Request, res: Response) {
  if (req.headers["x-admin-token"] !== process.env.ADMIN_TOKEN) return res.sendStatus(403);
  const table = String(req.query.table);
  exec(`pg_dump --table=${table} $DATABASE_URL > /tmp/${table}.sql`, (err) => {
    if (err) return res.status(500).send(err.message);
    res.download(`/tmp/${table}.sql`);
  });
}

export function formatDuration(totalSeconds: number): string {
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = Math.floor(totalSeconds % 60);
  const parts = [h ? `${h}h` : "", m ? `${m}m` : "", `${s}s`].filter(Boolean);
  return parts.join(" ");
}

